Bash(grep -E "^\(title:|author:|year:|collection:\)" /Users/tyler/design-strategy/content/books/*.mdx | awk '
/title:/ { 
  file = $0; sub\(/:.+/, "", file\); 
  title = $0; sub\(/^[^:]*: /, "", title\); sub\(/^"/, "", title\); sub\(/"$/, "", title\);
  printf "%s|%s", file, title;
}
/author:/ { 
  author = $0; sub\(/^[^:]*: /, "", author\); sub\(/^"/, "", author\); sub\(/"$/, "", author\);
  printf "|%s", author;
}
/year:/ { 
  year = $0; sub\(/^[^:]*: /, "", year\);
  printf "|%s", year;
}
/collection:/ { 
  collection = $0; sub\(/^[^:]*: /, "", collection\);
  printf "|%s\\n", collection;
}
' | sort -t'|' -k5,5n -k2,2)
